from collections import deque

class Solution:
    def minRunesToAdd(self, n: int, crystals: List[int], flowFrom: List[int], flowTo: List[int]) -> int:
        adj = [[] for _ in range(n)]
        for a, b in zip(flowFrom, flowTo):
            adj[a].append(b)
            adj[b].append(a)
        isCrystal = [False] * n
        for c in crystals:
            isCrystal[c] = True
        seen = [False] * n
        ans = 0
        for s in range(n):
            if seen[s]:
                continue
            seen[s] = True
            q = deque([s])
            has = False
            while q:
                u = q.popleft()
                if isCrystal[u]:
                    has = True
                for v in adj[u]:
                    if not seen[v]:
                        seen[v] = True
                        q.append(v)
            if not has:
                ans += 1
        return ans

