class Solution {
public:
    int minRunesToAdd(int n, vector<int>& crystals, vector<int>& flowFrom, vector<int>& flowTo) {
        vector<vector<int>> adj(n);
        for (size_t i = 0; i < flowFrom.size(); i++) {
            adj[flowFrom[i]].push_back(flowTo[i]);
            adj[flowTo[i]].push_back(flowFrom[i]);
        }
        vector<char> isC(n, 0), seen(n, 0);
        for (int c : crystals) isC[c] = 1;
        int ans = 0;
        for (int s = 0; s < n; s++) {
            if (seen[s]) continue;
            vector<int> st{s};
            seen[s] = 1;
            bool has = false;
            while (!st.empty()) {
                int u = st.back(); st.pop_back();
                if (isC[u]) has = true;
                for (int v : adj[u]) if (!seen[v]) { seen[v] = 1; st.push_back(v); }
            }
            if (!has) ans++;
        }
        return ans;
    }
};

