class Solution {
    public int minRunesToAdd(int n, int[] crystals, int[] flowFrom, int[] flowTo) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int i = 0; i < flowFrom.length; i++) {
            adj.get(flowFrom[i]).add(flowTo[i]);
            adj.get(flowTo[i]).add(flowFrom[i]);
        }
        boolean[] isC = new boolean[n], seen = new boolean[n];
        for (int c : crystals) isC[c] = true;
        int ans = 0;
        Deque<Integer> st = new ArrayDeque<>();
        for (int s = 0; s < n; s++) {
            if (seen[s]) continue;
            seen[s] = true;
            st.push(s);
            boolean has = false;
            while (!st.isEmpty()) {
                int u = st.pop();
                if (isC[u]) has = true;
                for (int v : adj.get(u)) if (!seen[v]) { seen[v] = true; st.push(v); }
            }
            if (!has) ans++;
        }
        return ans;
    }
}

