class Solution:
    def minRunesToAdd(self, n: int, crystals: List[int], flowFrom: List[int], flowTo: List[int]) -> int:
        parent = list(range(n))
        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x
        hasC = [False] * n
        for c in crystals:
            hasC[c] = True
        for a, b in zip(flowFrom, flowTo):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb
                hasC[rb] = hasC[rb] or hasC[ra]
        return len({find(i) for i in range(n) if not hasC[find(i)]})

