class Solution {
    vector<int> p;
    int find(int x) { while (p[x] != x) { p[x] = p[p[x]]; x = p[x]; } return x; }
public:
    int minRunesToAdd(int n, vector<int>& crystals, vector<int>& flowFrom, vector<int>& flowTo) {
        p.resize(n);
        iota(p.begin(), p.end(), 0);
        vector<char> hasC(n, 0);
        for (int c : crystals) hasC[c] = 1;
        for (size_t i = 0; i < flowFrom.size(); i++) {
            int ra = find(flowFrom[i]), rb = find(flowTo[i]);
            if (ra != rb) { p[ra] = rb; hasC[rb] |= hasC[ra]; }
        }
        unordered_set<int> bad;
        for (int i = 0; i < n; i++) {
            int r = find(i);
            if (!hasC[r]) bad.insert(r);
        }
        return bad.size();
    }
};

