        for (int i = 0; i < n; i++) p[i] = i;
        boolean[] hasC = new boolean[n];
        for (int c : crystals) hasC[c] = true;
        for (int i = 0; i < flowFrom.length; i++) {
            int ra = find(flowFrom[i]), rb = find(flowTo[i]);
            if (ra != rb) { p[ra] = rb; hasC[rb] |= hasC[ra]; }
        }
        Set<Integer> bad = new HashSet<>();
        for (int i = 0; i < n; i++) {
            int r = find(i);
            if (!hasC[r]) bad.add(r);
        }
        return bad.size();
    }
}

